import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { useCurrentSheet } from '../session/session';

/** A sheet's holiday as the store holds it: a date (YYYY-MM-DD), on the sheet at most once. Adding one works out
 *  again the due-by of every claim not SETTLED or VOID whose due-by is on or after it, over the holidays now. */
export type Holiday = { id: number; date: string };

export const holidaysQueryKey = (sheetId: string) => ['sheet', sheetId, 'holidays'] as const;

export const holidaysPath = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/holidays`;

/** The sheet's holidays, by date. */
export function useHolidays() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: holidaysQueryKey(sheet ?? ''),
    queryFn: () => getJson<Holiday[]>(holidaysPath(sheet ?? '')),
    enabled: !!sheet,
  });
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../api/submitOnce';
import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { claimsQueryKey } from '../claims/claims';
import { peopleQueryKey } from '../people/people';
import { holidaysPath, holidaysQueryKey, useHolidays, type Holiday } from './holidays';

// The sheet's holidays, and the entry that adds one. A date that is not a calendar date, or one already on the
// list, is refused by the server and shows the error beside the entry, which goes as soon as the entry changes.
function Holidays() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const holidays = useHolidays();
  const [date, setDate] = useState('');
  const queryClient = useQueryClient();
  const add = useMutation({
    mutationFn: (body: { date: string }) => postJson<Holiday>(holidaysPath(sheet ?? ''), body, user),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: holidaysQueryKey(sheet ?? '') });
      // Adding a holiday can move claims' due-by, and so their figures.
      await queryClient.invalidateQueries({ queryKey: claimsQueryKey(sheet ?? '') });
      await queryClient.invalidateQueries({ queryKey: peopleQueryKey(sheet ?? '') });
      setDate('');
    },
  });
  const submit = useSubmitOnce(add);

  if (!user || !sheet) return null;
  return (
    <section data-testid="holidays">
      <h2>Holidays</h2>
      <ul>
        {(holidays.data ?? []).map((h) => (
          <li key={h.id} data-testid={`holiday-row-${h.date}`}>{h.date}</li>
        ))}
      </ul>
      <form
        data-testid="holiday-form"
        onSubmit={(e) => {
          e.preventDefault();
          submit({ date });
        }}
      >
        <input
          data-testid="holiday-date"
          placeholder="Date (YYYY-MM-DD)"
          value={date}
          onChange={(e) => { setDate(e.target.value); add.reset(); }}
        />
        <button type="submit" data-testid="holiday-add" disabled={add.isPending}>
          Add holiday
        </button>
        {add.isError && (
          <span data-testid="holiday-error">A holiday must be a calendar date not already on the list.</span>
        )}
      </form>
    </section>
  );
}

export const contribution = HomeMain.fill({ order: 6.5, Component: Holidays });
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}
import { defineSlot } from '../Slot';

/** The home page's body: every panel on the one screen at `/` contributes itself here. */
export const HomeMain = defineSlot('home.main');
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
// A non-2xx answer: its status tells a refusal (400) from a conflict with someone else's save (409).
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

// The as-of view: while the screen's `asof` search param holds a date, every read of a sheet asks for the
// sheet as it stood at the end of that date, and every change is refused here, before it reaches the store
// (so each form and action shows its usual error). Loading a sheet (PUT /api/sheets/<id>) is not a change.
export const ASOF_PARAM = 'asof';

/** The date the screen shows the sheet as of (YYYY-MM-DD), or '' while it shows the sheet as it is now. */
export function currentAsOf(): string {
  const raw = new URLSearchParams(window.location.search).get(ASOF_PARAM) ?? '';
  try {
    const parsed: unknown = JSON.parse(raw);
    return typeof parsed === 'string' ? parsed : raw;
  } catch {
    return raw;
  }
}

const isSheetLoad = (path: string) => /^\/api\/sheets\/[^/?]+$/.test(path);

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const asOf = currentAsOf();
  if (asOf && init?.method && init.method !== 'GET' && !isSheetLoad(path)) {
    throw new HttpError(`${init.method} ${path} -> refused while the sheet is shown as of ${asOf}`, 400);
  }
  if (asOf && !init?.method && path.startsWith('/api/sheets/')) {
    path += `${path.includes('?') ? '&' : '?'}asOf=${encodeURIComponent(asOf)}`;
  }
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

// A change sends the signed-in name (`user`) as `X-User`, URI-encoded (a header is Latin-1 only),
// so the server records who made it.
const jsonHeaders = (user?: string): Record<string, string> =>
  user ? { 'Content-Type': 'application/json', 'X-User': encodeURIComponent(user) } : { 'Content-Type': 'application/json' };

export function postJson<T>(path: string, body: unknown, user?: string): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: jsonHeaders(user),
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body?: unknown, user?: string): Promise<T> {

